'use strict';
// Файлы Excel (.xlsx) без библиотек: запись — zip без сжатия, чтение — zip со сжатием через DecompressionStream('deflate-raw'), плюс CSV
/* ═════════════ Excel: запись и чтение .xlsx ═════════════ */
const XL_MIME='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
const XL_CRC=(()=>{const t=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=c&1?0xEDB88320^(c>>>1):c>>>1;t[n]=c>>>0}return t})();
function xlCrc(b){let c=0xFFFFFFFF;for(let i=0;i<b.length;i++)c=XL_CRC[(c^b[i])&255]^(c>>>8);return (c^0xFFFFFFFF)>>>0}
// Архив zip без сжатия: files — [[путь, текст]]
function xlZip(files){const enc=new TextEncoder();const parts=[],cd=[];let off=0;
  files.forEach(([n,txt])=>{const nb=enc.encode(n),d=enc.encode(txt),crc=xlCrc(d);
    const h=new DataView(new ArrayBuffer(30));h.setUint32(0,0x04034b50,true);h.setUint16(4,20,true);h.setUint16(6,0x0800,true);h.setUint16(12,0x21,true);h.setUint32(14,crc,true);h.setUint32(18,d.length,true);h.setUint32(22,d.length,true);h.setUint16(26,nb.length,true);
    parts.push(new Uint8Array(h.buffer),nb,d);
    const c=new DataView(new ArrayBuffer(46));c.setUint32(0,0x02014b50,true);c.setUint16(4,20,true);c.setUint16(6,20,true);c.setUint16(8,0x0800,true);c.setUint16(14,0x21,true);c.setUint32(16,crc,true);c.setUint32(20,d.length,true);c.setUint32(24,d.length,true);c.setUint16(28,nb.length,true);c.setUint32(42,off,true);
    cd.push(new Uint8Array(c.buffer),nb);off+=30+nb.length+d.length});
  const cdl=cd.reduce((a,x)=>a+x.length,0);const e=new DataView(new ArrayBuffer(22));e.setUint32(0,0x06054b50,true);e.setUint16(8,files.length,true);e.setUint16(10,files.length,true);e.setUint32(12,cdl,true);e.setUint32(16,off,true);
  return new Blob([...parts,...cd,new Uint8Array(e.buffer)],{type:XL_MIME})}
const xlEsc=s=>String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g,'');
const xlCol=n=>{let s='';n++;while(n){const m=(n-1)%26;s=String.fromCharCode(65+m)+s;n=(n-m-1)/26}return s};
const xlColN=s=>{let n=0;for(const ch of s)n=n*26+ch.charCodeAt(0)-64;return n-1};
// Стили ячеек: 0 обычная (защищена), 1 заголовок, 2 поле ввода, 3 серая защищённая (показатель не ведётся), 4 поле ввода «проверено», 5 защищённая голубая (ИНН и название), 6 текст с переносом
const XL_ST={head:1,input:2,off:3,checked:4,key:5,wrap:6};
const XL_STYLES=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="2"><font><sz val="11"/><name val="Calibri"/></font><font><b/><sz val="11"/><name val="Calibri"/></font></fonts><fills count="5"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FFE7E6E6"/><bgColor indexed="64"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FFE2EFDA"/><bgColor indexed="64"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FFDDEBF7"/><bgColor indexed="64"/></patternFill></fill></fills><borders count="2"><border><left/><right/><top/><bottom/><diagonal/></border><border><left style="thin"><color rgb="FFBFBFBF"/></left><right style="thin"><color rgb="FFBFBFBF"/></right><top style="thin"><color rgb="FFBFBFBF"/></top><bottom style="thin"><color rgb="FFBFBFBF"/></bottom><diagonal/></border></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="7"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="1" fillId="2" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment wrapText="1" vertical="top"/></xf><xf numFmtId="4" fontId="0" fillId="0" borderId="1" xfId="0" applyNumberFormat="1" applyBorder="1" applyProtection="1"><protection locked="0"/></xf><xf numFmtId="0" fontId="0" fillId="2" borderId="1" xfId="0" applyFill="1" applyBorder="1"/><xf numFmtId="4" fontId="0" fillId="3" borderId="1" xfId="0" applyNumberFormat="1" applyFill="1" applyBorder="1" applyProtection="1"><protection locked="0"/></xf><xf numFmtId="49" fontId="0" fillId="4" borderId="1" xfId="0" applyNumberFormat="1" applyFill="1" applyBorder="1"/><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0" applyAlignment="1"><alignment wrapText="1" vertical="top"/></xf></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>`;
// Лист: {name, rows:[[ячейка]], widths:[ширина], freeze:{x,y}, protect}; ячейка — значение или {v, s} (s — номер стиля из XL_ST)
function xlSheet(sh){const rows=sh.rows.map((r,ri)=>`<row r="${ri+1}">${r.map((c,ci)=>{if(c==null)return '';const o=typeof c==='object'?c:{v:c};const ref=xlCol(ci)+(ri+1);const st=o.s?` s="${o.s}"`:'';
    if(o.v==null||o.v==='')return st?`<c r="${ref}"${st}/>`:'';if(typeof o.v==='number'&&isFinite(o.v))return `<c r="${ref}"${st}><v>${o.v}</v></c>`;return `<c r="${ref}"${st} t="inlineStr"><is><t xml:space="preserve">${xlEsc(o.v)}</t></is></c>`}).join('')}</row>`).join('');
  const fr=sh.freeze?`<pane xSplit="${sh.freeze.x||0}" ySplit="${sh.freeze.y||0}" topLeftCell="${xlCol(sh.freeze.x||0)}${(sh.freeze.y||0)+1}" activePane="bottomRight" state="frozen"/>`:'';
  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0">${fr}</sheetView></sheetViews><sheetFormatPr defaultRowHeight="15"/>${sh.widths?`<cols>${sh.widths.map((w,i)=>`<col min="${i+1}" max="${i+1}" width="${w}" customWidth="1"/>`).join('')}</cols>`:''}<sheetData>${rows}</sheetData>${sh.protect?'<sheetProtection sheet="1" objects="1" scenarios="1" formatColumns="0" formatRows="0" sort="0" autoFilter="0"/>':''}</worksheet>`}
function xlWrite(sheets){const ns=sheets.map((s,i)=>i+1);
  return xlZip([['[Content_Types].xml',`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>${ns.map(n=>`<Override PartName="/xl/worksheets/sheet${n}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')}</Types>`],
    ['_rels/.rels','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>'],
    ['xl/workbook.xml',`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>${sheets.map((s,i)=>`<sheet name="${xlEsc(s.name.slice(0,31))}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join('')}</sheets></workbook>`],
    ['xl/_rels/workbook.xml.rels',`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${ns.map(n=>`<Relationship Id="rId${n}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${n}.xml"/>`).join('')}<Relationship Id="rId${sheets.length+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>`],
    ['xl/styles.xml',XL_STYLES],...sheets.map((s,i)=>[`xl/worksheets/sheet${i+1}.xml`,xlSheet(s)])])}
// Скачать файл; в артефакте claude.ai браузер может не дать сохранить — тогда файл виден только в предпросмотре
function xlSave(blob,name){try{const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.rel='noopener';document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},2000);return true}catch(e){return false}}
// Чтение: первый лист .xlsx (или CSV) → массив строк, в каждой ячейки по номерам столбцов; числа — числами, остальное — текстом
async function xlUnzip(buf){const u=new Uint8Array(buf),dv=new DataView(buf);let e=u.length-22;while(e>=0&&dv.getUint32(e,true)!==0x06054b50)e--;if(e<0)throw new Error('Файл не похож на .xlsx');
  const n=dv.getUint16(e+10,true);let p=dv.getUint32(e+16,true);const out={};const dec=new TextDecoder();
  for(let k=0;k<n;k++){if(dv.getUint32(p,true)!==0x02014b50)throw new Error('Файл .xlsx повреждён');const meth=dv.getUint16(p+10,true),csz=dv.getUint32(p+20,true),nl=dv.getUint16(p+28,true),el=dv.getUint16(p+30,true),cl=dv.getUint16(p+32,true),lo=dv.getUint32(p+42,true);
    const name=dec.decode(u.subarray(p+46,p+46+nl));p+=46+nl+el+cl;const s0=lo+30+dv.getUint16(lo+26,true)+dv.getUint16(lo+28,true);out[name]={meth,data:u.subarray(s0,s0+csz)}}
  return async name=>{const f=out[name];if(!f)return null;if(f.meth===0)return dec.decode(f.data);if(f.meth!==8)throw new Error('Неизвестный способ сжатия в .xlsx');
    if(typeof DecompressionStream==='undefined')throw new Error('Браузер не умеет распаковывать .xlsx — обновите браузер или сохраните файл как CSV');
    return await new Response(new Blob([f.data]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).text()}}
const xlTags=(doc,t)=>[...doc.getElementsByTagNameNS('*',t)];
async function xlRead(file){const name=file.name||'';
  if(/\.(csv|txt|tsv)$/i.test(name)){const t=(await file.text()).replace(/^﻿/,'');const ls=t.split(/\r?\n/).filter(l=>l.trim());const d=ls[0]&&ls[0].includes('\t')?'\t':ls[0]&&ls[0].split(';').length>=ls[0].split(',').length?';':',';
    return ls.map(l=>{const out=[];let cur='',q=false;for(let i=0;i<l.length;i++){const ch=l[i];if(q){if(ch==='"'&&l[i+1]==='"'){cur+='"';i++}else if(ch==='"')q=false;else cur+=ch}else if(ch==='"')q=true;else if(ch===d){out.push(cur);cur=''}else cur+=ch}out.push(cur);return out})}
  const get=await xlUnzip(await file.arrayBuffer());const P=new DOMParser();const X=s=>P.parseFromString(s,'application/xml');
  const wb=X(await get('xl/workbook.xml')||'');const sh=xlTags(wb,'sheet')[0];if(!sh)throw new Error('В файле нет листов');
  const rid=sh.getAttribute('r:id')||sh.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id');
  const rels=X(await get('xl/_rels/workbook.xml.rels')||'<x/>');const rel=xlTags(rels,'Relationship').find(r=>r.getAttribute('Id')===rid);let path=rel?rel.getAttribute('Target'):'worksheets/sheet1.xml';path=path.startsWith('/')?path.slice(1):'xl/'+path.replace(/^\.\//,'');
  const sst=await get('xl/sharedStrings.xml');const ss=sst?xlTags(X(sst),'si').map(si=>xlTags(si,'t').map(t=>t.textContent).join('')):[];
  const ws=X(await get(path)||'');const rows=[];
  xlTags(ws,'c').forEach(c=>{const m=/^([A-Z]+)(\d+)$/.exec(c.getAttribute('r')||'');if(!m)return;const ci=xlColN(m[1]),ri=+m[2]-1;const t=c.getAttribute('t');const v=xlTags(c,'v')[0];let val;
    if(t==='s')val=v?ss[+v.textContent]:'';else if(t==='inlineStr')val=xlTags(c,'t').map(x=>x.textContent).join('');else if(t==='str'||t==='e')val=v?v.textContent:'';else if(t==='b')val=v?v.textContent==='1'?'ИСТИНА':'ЛОЖЬ':'';else val=v&&v.textContent!==''?+v.textContent:'';
    (rows[ri]=rows[ri]||[])[ci]=val});
  for(let i=0;i<rows.length;i++)rows[i]=rows[i]||[];return rows}
